.deal-stack { display: grid; gap: 22px; }
.deal-eyebrow {
  font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase;
  font-weight: 700; opacity: 0.95;
}
.deal h3 {
  font-family: 'Fraunces', serif;
  font-weight: 500;
  font-size: clamp(28px, 3vw, 42px);
  letter-spacing: -0.02em;
  margin: 14px 0 6px;
  max-width: 420px;
  line-height: 1.05;
}
.deal p { opacity: 0.92; max-width: 380px; font-size: 14.5px; line-height: 1.5; margin: 0; }
.deal .btn { align-self: flex-start; }
.deal .btn-light { background: #fff; color: var(--ink); }

/* Countdown */
.countdown { display: flex; gap: 10px; margin-top: 18px; }
.cd-cell {
  background: rgba(255,255,255,0.18);
  backdrop-filter: blur(6px);
  border: 1px solid rgba(255,255,255,0.25);
  border-radius: 10px;
  padding: 8px 12px;
  text-align: center;
  min-width: 56px;
}
.cd-cell b { display: block; font-size: 20px; font-family: 'Fraunces', serif; font-weight: 500; }
.cd-cell span { font-size: 10px; text-transform: uppercase; letter-spacing: 0.08em; opacity: 0.85; }

/* Small deals */
.deal.small-1, .deal.small-2 { min-height: 198px; padding: 28px; }
.deal.small-1 h3, .deal.small-2 h3 { font-size: 26px; margin: 8px 0 4px; }

/* ============ Editorial ============ */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.editorial {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  cursor: pointer;
  transition: transform .25s ease, box-shadow .25s ease;
}
.editorial:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.editorial-img {
  aspect-ratio: 4 / 3;
  background-size: cover; background-position: center;
  position: relative;
}
.editorial-cat {
  position: absolute; top: 16px; left: 16px;
  background: var(--surface); color: var(--ink);
  font-size: 11px; font-weight: 700; letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 6px 10px; border-radius: 999px;
}
.editorial-body { padding: 22px 24px 26px; }
.editorial-meta { font-size: 12px; color: var(--muted); letter-spacing: 0.04em; }
.editorial-title {
  font-family: 'Fraunces', serif;
  font-weight: 500;
  font-size: 22px;
  letter-spacing: -0.015em;
  line-height: 1.2;
  margin: 8px 0 10px;
}
.editorial-excerpt { font-size: 14px; color: var(--ink-soft); line-height: 1.55; margin: 0 0 16px; }
.read-more { font-size: 13px; font-weight: 600; display: inline-flex; gap: 6px; transition: gap .2s; }
.read-more:hover { gap: 10px; }

/* ============ Marquee ============ */
.values {
  background: var(--ink);
  color: #fff;
  padding: 26px 0;
  overflow: hidden;
}
.values-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.value {
  display: flex; align-items: center; gap: 14px;
}
.value svg { color: #ffd25a; flex-shrink: 0; }
.value b { display: block; font-size: 14px; font-weight: 600; }
.value span { font-size: 12.5px; opacity: 0.7; }

/* ============ Newsletter ============ */
.newsletter {
  background: linear-gradient(180deg, #fafaf7 0%, #efece4 100%);
  padding: 80px 0;
  text-align: center;
}
.newsletter h2 {
  font-family: 'Fraunces', serif;
  font-weight: 500;
  font-size: clamp(32px, 4vw, 52px);
  letter-spacing: -0.02em;
  margin: 0 0 12px;
  line-height: 1.05;
}
.newsletter p { color: var(--ink-soft); max-width: 480px; margin: 0 auto 28px; font-size: 15px; }
.subscribe {
  display: flex;
  max-width: 460px; margin: 0 auto;
  background: #fff;
  border-radius: 999px;
  padding: 5px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--line);
}
.subscribe input {
  flex: 1; border: 0; background: transparent;
  padding: 12px 18px; font-size: 14.5px; outline: none; color: var(--ink);
  font-family: inherit;
}
.subscribe button {
  background: var(--ink); color: #fff;
  padding: 12px 22px; border-radius: 999px;
  font-size: 14px; font-weight: 600;
  transition: background .2s;
}
.subscribe button:hover { background: var(--accent); }

/* ============ Footer ============ */
.footer { background: #0e0e10; color: #c8c8cd; padding: 60px 0 32px; }
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, 1fr);
  gap: 32px;
  padding-bottom: 40px;
  border-bottom: 1px solid #232328;
}
.footer h4 { color: #fff; font-size: 13px; letter-spacing: 0.08em; text-transform: uppercase; margin: 0 0 16px; }
.footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.footer a { color: #c8c8cd; font-size: 14px; transition: color .2s; }
.footer a:hover { color: var(--accent); }
.footer-brand .brand { color: #fff; }
.footer-brand p { font-size: 14px; line-height: 1.6; max-width: 320px; margin: 14px 0 18px; opacity: 0.8; }
.socials { display: flex; gap: 10px; }
.socials a {
  width: 38px; height: 38px; border-radius: 999px;
  background: #1c1c20; display: inline-flex; align-items: center; justify-content: center;
  transition: background .2s;
}
.socials a:hover { background: var(--accent); color: #fff; }
.copyright {
  display: flex; justify-content: space-between; flex-wrap: wrap; gap: 16px;
  padding-top: 24px; font-size: 12.5px; color: #8a8a93;
}

/* ============ Responsive ============ */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .hero-card { grid-template-columns: 1fr; min-height: auto; }
  .hero-content { padding: 48px 40px 24px; }
  .hero-visual { min-height: 320px; }
}
@media (max-width: 720px) {
  .container { padding: 0 18px; }
  .nav { display: none; }
  .header-inner { grid-template-columns: 1fr 1fr; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .deals { grid-template-columns: 1fr; }
  .values-row { grid-template-columns: 1fr 1fr; gap: 18px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .hero-content { padding: 36px 24px 20px; }
  .deal { padding: 28px; }
  .section { padding: 40px 0; }
}
