  border-radius: var(--radius);
  overflow: hidden;
  transition: transform .25s ease, box-shadow .25s ease;
  cursor: pointer;
  position: relative;
}
.product:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.product-img {
  aspect-ratio: 4 / 5;
  background: var(--tag);
  position: relative;
  overflow: hidden;
}
.product-img img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform .5s ease;
}
.product:hover .product-img img { transform: scale(1.05); }

.tag {
  position: absolute; top: 12px; left: 12px;
  background: var(--surface); color: var(--ink);
  font-size: 11px; font-weight: 700; letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 5px 10px; border-radius: 999px;
}
.tag.new { background: var(--ink); color: #fff; }
.tag.sale { background: var(--accent); color: #fff; }

.fav {
  position: absolute; top: 10px; right: 10px;
  width: 36px; height: 36px; border-radius: 999px;
  background: rgba(255,255,255,0.9);
  display: inline-flex; align-items: center; justify-content: center;
  transition: background .2s, transform .2s;
}
.fav:hover { background: #fff; transform: scale(1.06); }
.fav.active svg { fill: var(--accent); stroke: var(--accent); }

.quick-add {
  position: absolute; left: 12px; right: 12px; bottom: 12px;
  background: var(--ink); color: #fff;
  padding: 11px 14px;
  border-radius: 10px;
  font-size: 13px; font-weight: 600;
  display: flex; align-items: center; justify-content: center; gap: 8px;
  opacity: 0; transform: translateY(8px);
  transition: opacity .25s, transform .25s;
}
.product:hover .quick-add { opacity: 1; transform: translateY(0); }

.product-body { padding: 16px 4px 8px; }
.product-cat { font-size: 11.5px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; }
.product-name {
  font-size: 15px; font-weight: 500; margin: 4px 0 6px;
  line-height: 1.3;
}
.product-price { display: flex; align-items: center; gap: 8px; font-size: 14.5px; }
.price { font-weight: 600; }
.price-old { color: var(--muted); text-decoration: line-through; font-size: 13px; }
.swatches { display: flex; gap: 5px; margin-top: 8px; }
.swatch-dot {
  width: 14px; height: 14px; border-radius: 999px;
  border: 1.5px solid #fff;
  outline: 1px solid var(--line);
}

/* ============ Deals (split banners) ============ */
.deals {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 22px;
}
.deal {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 320px;
  padding: 40px;
  display: flex; flex-direction: column; justify-content: space-between;
  color: #fff;
  isolation: isolate;
}
.deal::after {
  content: ''; position: absolute; inset: 0; z-index: -1;
  background-position: center; background-size: cover;
  transition: transform .5s ease;
}
.deal:hover::after { transform: scale(1.04); }
.deal::before {
  content: ''; position: absolute; inset: 0; z-index: -1;
  background: linear-gradient(120deg, rgba(0,0,0,.55), rgba(0,0,0,.1));
}
.deal.large { min-height: 420px; }
.deal.large::after {
  background-image: url('https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1400&q=80');
}
