  margin: 14px 0 6px;
  max-width: 420px;
  line-height: 1.05;
}
.deal p { opacity: 0.92; max-width: 380px; font-size: 14.5px; line-height: 1.5; margin: 0; }
.deal .btn { align-self: flex-start; }
.deal .btn-light { background: #fff; color: var(--ink); }

