  background: linear-gradient(180deg, #fafaf7 0%, #efece4 100%);
  padding: 80px 0;
  text-align: center;
}
.newsletter h2 {
  font-family: 'Fraunces', serif;
  font-weight: 500;
  font-size: clamp(32px, 4vw, 52px);
  letter-spacing: -0.02em;
  margin: 0 0 12px;
  line-height: 1.05;
