.copyright {
  display: flex; justify-content: space-between; flex-wrap: wrap; gap: 16px;
  padding-top: 24px; font-size: 12.5px; color: #8a8a93;
}

/* ============ Responsive ============ */
@media (max-width: 1024px) {
