function FeaturedProducts({ onAdd }) {
  const [active, setActive] = useState("All");
  const [favs, setFavs] = useState(new Set([2, 5]));

  const filtered = useMemo(
    () => active === "All" ? PRODUCTS : PRODUCTS.filter(p => p.cat === active),
    [active]
  );

  const toggleFav = (id) => {
    setFavs(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  return (
    <section className="section container">
      <div className="section-head">
        <div>
          <h2>Featured this week</h2>
          <p>Hand-picked pieces from the new collection — restocked Mondays and rarely on sale.</p>
        </div>
        <a href="#" className="section-link">Shop all <Icon name="arrow" size={14} /></a>
      </div>
      <div className="pills" style={{ marginBottom: 28 }}>
        {CATEGORIES.map(c => (
          <button
            key={c}
            className={"pill" + (c === active ? " active" : "")}
            onClick={() => setActive(c)}>
            {c}
          </button>
        ))}
      </div>
      <div className="product-grid">
        {filtered.map(p => (
          <ProductCard
            key={p.id}
            product={p}
            faved={favs.has(p.id)}
            onFav={() => toggleFav(p.id)}
            onAdd={() => onAdd(p)} />
        ))}
      </div>
    </section>
  );
}

function Countdown() {
  const target = useMemo(() => Date.now() + 1000 * 60 * 60 * 36, []);
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  const diff = Math.max(0, target - now);
  const h = String(Math.floor(diff / 3.6e6)).padStart(2, "0");
  const m = String(Math.floor((diff / 6e4) % 60)).padStart(2, "0");
  const s = String(Math.floor((diff / 1e3) % 60)).padStart(2, "0");
  return (
    <div className="countdown">
      <div className="cd-cell"><b>{h}</b><span>Hours</span></div>
      <div className="cd-cell"><b>{m}</b><span>Mins</span></div>
      <div className="cd-cell"><b>{s}</b><span>Secs</span></div>
    </div>
  );
}

